async ({ session: { outline, info, inspectEntry } }) => {
  const o = await outline({ limit: 500, previewChars: 400 });
  const collapsed = o.entries.filter((e: any) => e.preview.startsWith("[Pit: collapsed"));
  const byState: Record<string, number> = {};
  for (const e of o.entries as any[]) byState[`${e.role}:${e.state}`] = (byState[`${e.role}:${e.state}`] ?? 0) + 1;
  const ids = [...(collapsed[1]?.preview ?? "").matchAll(/inspectEntry\("(\d+)"\)/g)].map((m) => m[1]);
  const originals = await Promise.all(ids.map(async (id) => {
    const r: any = await inspectEntry(id, { limit: 300 });
    return { id, state: r.state, chars: r.original?.text?.length, head: r.original?.text?.slice(0, 160) };
  }));
  const i: any = await info();
  return { contextTokens: i.contextTokens, entries: o.entries.length, byState, collapsed: collapsed.length, sample: collapsed[1]?.preview, originals };
}
